// Helper function to read SQL statement from input data
static char*  id_000008_read_sql_from_data(const uint8_t* data, size_t size, size_t* out_len) {
    if (size == 0) return nullptr;
    
    // Find null terminator or use entire buffer
    size_t sql_len = 0;
    while (sql_len < size && data[sql_len] != 0) {
        sql_len++;
    }
    
    char* sql = (char*)malloc(sql_len + 1);
    if (!sql) return nullptr;
    
    memcpy(sql, data, sql_len);
    sql[sql_len] = '\0';
    
    if (out_len) *out_len = sql_len;
    return sql;
}

